<!-- Language Switcher Pill -->
<div class="flex items-center bg-slate-100 p-1 rounded-full border border-border-light shadow-inner" aria-label="Language selection" role="group">
  <button type="button" class="lang-toggle-btn flex items-center gap-1 px-2.5 py-1 text-[10px] sm:text-xs font-bold rounded-full transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-accent bg-white shadow-sm text-primary cursor-pointer" data-lang="en" aria-pressed="true">
    <svg class="w-3 h-3 sm:w-3.5 sm:h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>
    EN
  </button>
  <button type="button" class="lang-toggle-btn flex items-center gap-1 px-2.5 py-1 text-[10px] sm:text-xs font-bold rounded-full transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-accent text-primary/60 hover:text-primary cursor-pointer" data-lang="id" aria-pressed="false">
    ID
  </button>
</div>
